BEGIN;

INSERT INTO public.data_providers (
    code, name, provider_type, official_source, base_url, is_active
) VALUES
    ('BEA', 'U.S. Bureau of Economic Analysis', 'economic', true, 'https://www.bea.gov', true),
    ('BINANCE', 'Binance Public Market Data API', 'market', true, 'https://data-api.binance.vision', true),
    ('BLS', 'U.S. Bureau of Labor Statistics', 'economic', true, 'https://www.bls.gov', true),
    ('FED', 'Federal Reserve FOMC Calendar', 'economic', true, 'https://www.federalreserve.gov', true),
    ('KAP', 'Kamuyu Aydınlatma Platformu', 'earnings', true, 'https://www.kap.org.tr', true),
    ('OFFICIAL_IR', 'Official Investor Relations', 'earnings', true, NULL, true),
    ('TCMB', 'TCMB Takvimi', 'economic', true, 'https://www.tcmb.gov.tr', true),
    ('TEFAS', 'Türkiye Elektronik Fon Alım Satım Platformu', 'market', true, 'https://www.tefas.gov.tr', true),
    ('TUIK', 'TÜİK Veri Takvimi', 'economic', true, 'https://takvim.tuik.gov.tr', true),
    ('YAHOO_FINANCE', 'Yahoo Finance', 'earnings', false, 'https://finance.yahoo.com', true)
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    provider_type = EXCLUDED.provider_type,
    official_source = EXCLUDED.official_source,
    base_url = EXCLUDED.base_url,
    is_active = EXCLUDED.is_active
WHERE (data_providers.name, data_providers.provider_type,
       data_providers.official_source, data_providers.base_url,
       data_providers.is_active)
      IS DISTINCT FROM
      (EXCLUDED.name, EXCLUDED.provider_type, EXCLUDED.official_source,
       EXCLUDED.base_url, EXCLUDED.is_active);

